//! Wraps wgpu30 native offscreen raster+readback. No graphics API reimplementation.
//! CPU fallback uses existing lit_raster, not a promised software driver.
use super::{vertex_stream::Stream,pbr::Material,lighting_stage::Light};use crate::{camera_projection::Camera,effects::Frame};
#[derive(serde::Serialize)]pub struct Status{pub actual_backend:String,pub fallback_reason:Option<String>,pub mode:&'static str}
/// Timeout-bounded future driving without adding an executor crate. No unsafe.
#[cfg(all(feature="gpu3d",any(target_os="linux",target_os="windows",target_os="macos")))]
fn wait<F:std::future::Future>(future:F)->Result<F::Output,String>{use std::task::{Wake,Waker,Context,Poll};struct Thread(std::thread::Thread);impl Wake for Thread{fn wake(self:std::sync::Arc<Self>){self.0.unpark();}fn wake_by_ref(self:&std::sync::Arc<Self>){self.0.unpark();}}let w=Waker::from(std::sync::Arc::new(Thread(std::thread::current())));let mut context=Context::from_waker(&w);let mut future=Box::pin(future);let start=std::time::Instant::now();loop{crate::guard::check();if let Poll::Ready(x)=future.as_mut().poll(&mut context){return Ok(x);}if start.elapsed()>std::time::Duration::from_secs(20){return Err("GPU adapter/device future timeout".into());}std::thread::park_timeout(std::time::Duration::from_millis(10));}}
/// Explicit CPU PBR fallback differs from the initial GPU normal-only pass.
/// Auto mode does not silently change shading: GPU requested normal pass only.
pub fn render_cpu_pbr(s:&Stream,c:&Camera,w:usize,h:usize,m:&Material,l:&[Light])->Result<(Frame,Status),String>{let o=super::lit_raster::render(s,c,w,h,m,l)?;Ok((o.frame,Status{actual_backend:"cpu".into(),fallback_reason:None,mode:"direct_pbr"}))}
pub fn render_normal(s:&Stream,c:&Camera,w:usize,h:usize,software_only:bool,allow_cpu:bool)->Result<(Frame,Status),String>{s.validate()?;c.validate()?;if w==0||h==0||w>4096||h>4096{return Err("viewport1..4096".into());}
 #[cfg(all(feature="gpu3d",any(target_os="linux",target_os="windows",target_os="macos")))]
 let result=gpu_normal(s,c,w,h,software_only);
 #[cfg(not(all(feature="gpu3d",any(target_os="linux",target_os="windows",target_os="macos"))))]
 let result:Result<(Frame,String),String>={let _=software_only;Err("native gpu3d feature not compiled for target".into())};
 match result{Ok((f,name))=>Ok((f,Status{actual_backend:name,fallback_reason:None,mode:"world_normal"})),Err(e)=>{if !allow_cpu{return Err(e);}let f=cpu_normal(s,c,w,h)?;Ok((f,Status{actual_backend:"cpu".into(),fallback_reason:Some(e),mode:"world_normal"}))}}
}
fn cpu_normal(s:&Stream,c:&Camera,w:usize,h:usize)->Result<Frame,String>{normal_reference(s,c,w,h)}
fn normal_reference(s:&Stream,c:&Camera,w:usize,h:usize)->Result<Frame,String>{use crate::camera_projection::{Vertex,clip};let mut f=Frame::try_new(w,h)?;let mut depth=vec![f64::INFINITY;w*h];let projection=Camera{eye:[0.;3],pan:0.,tilt:0.,roll:0.,..*c};let edge=|a:[f64;3],b:[f64;3],x:f64,y:f64|(b[0]-a[0])*(y-a[1])-(b[1]-a[1])*(x-a[0]);for ids in &s.indices{crate::guard::check();let tri:Vec<_>=ids.iter().map(|i|{let v=s.vertices[*i as usize];Ok(Vertex{position:c.view(v.position.map(|v|v as f64))?,attributes:v.normal.map(|v|v as f64).to_vec()})}).collect::<Result<_,String>>()?;for t in clip(tri.try_into().map_err(|_|"triangle")?,c.near)?{let mut p=[[0.;3];3];for i in 0..3{p[i]=projection.project(t[i].position,w as u32,h as u32)?.ok_or("clip/projection mismatch")?;}let area=edge(p[0],p[1],p[2][0],p[2][1]);if area==0.{continue;}if !area.is_finite(){return Err("area overflow".into());}let bound=|j:usize,limit:usize|{(p.iter().map(|p|p[j]).fold(f64::INFINITY,f64::min).floor().clamp(0.,limit as f64) as usize,p.iter().map(|p|p[j]).fold(f64::NEG_INFINITY,f64::max).ceil().clamp(0.,limit as f64) as usize)};let(x0,x1)=bound(0,w);let(y0,y1)=bound(1,h);for y in y0..y1{crate::guard::check();for x in x0..x1{let b=[edge(p[1],p[2],x as f64+0.5,y as f64+0.5)/area,edge(p[2],p[0],x as f64+0.5,y as f64+0.5)/area,edge(p[0],p[1],x as f64+0.5,y as f64+0.5)/area];if b.iter().any(|v|*v<0.){continue;}let iz=(0..3).map(|i|b[i]/p[i][2]).sum::<f64>();if iz<=0.||!iz.is_finite(){return Err("inverse depth".into());}let z=1./iz;let id=y*w+x;if z>=depth[id]{continue;}let normal=super::vertex_stream::unit(std::array::from_fn(|j|(0..3).map(|i|b[i]*t[i].attributes[j]/p[i][2]).sum::<f64>()/iz))?;depth[id]=z;for j in 0..3{f.d[id*4+j]=(0.5+0.5*normal[j]) as f32;}f.d[id*4+3]=1.;}}}}Ok(f)}
#[cfg(all(feature="gpu3d",any(target_os="linux",target_os="windows",target_os="macos")))]
fn gpu_normal(s:&Stream,c:&Camera,w:usize,h:usize,software_only:bool)->Result<(Frame,String),String>{use wgpu::util::DeviceExt;use crate::camera_projection::{Vertex,clip};if wgpu::Instance::enabled_backend_features().is_empty(){return Err("no compiled backend".into());}let instance=wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle_from_env());let adapter=wait(instance.request_adapter(&wgpu::RequestAdapterOptions{force_fallback_adapter:software_only,compatible_surface:None,..Default::default()}))?.map_err(|e|e.to_string())?;let name=format!("wgpu:{:?}",adapter.get_info());let(device,queue)=wait(adapter.request_device(&wgpu::DeviceDescriptor::default()))?.map_err(|e|e.to_string())?;
 let projection=Camera{eye:[0.;3],pan:0.,tilt:0.,roll:0.,..*c};let mut bytes=Vec::new();let mut count=0u32;for ids in &s.indices{crate::guard::check();let tri=ids.iter().map(|i|{let v=s.vertices[*i as usize];Ok(Vertex{position:c.view(v.position.map(|v|v as f64))?,attributes:v.normal.map(|v|v as f64).to_vec()})}).collect::<Result<Vec<_>,String>>()?;for tri in clip(tri.try_into().map_err(|_|"triangle")?,c.near)?{for v in tri{let p=projection.project(v.position,w as u32,h as u32)?.ok_or("project clip")?;let z=p[2];let clip_pos=[(2.*p[0]/w as f64-1.)*z,(1.-2.*p[1]/h as f64)*z,z-c.near,z];for value in clip_pos.into_iter().chain(v.attributes){if !value.is_finite()||value.abs()>f32::MAX as f64{return Err("GPU vertex overflow".into());}bytes.extend((value as f32).to_le_bytes());}count+=1;}}}
 if count==0{return Ok((Frame::try_new(w,h)?,name));}let buffer=device.create_buffer_init(&wgpu::util::BufferInitDescriptor{label:Some("camera clipped raw vertices"),contents:&bytes,usage:wgpu::BufferUsages::VERTEX});let size=wgpu::Extent3d{width:w as u32,height:h as u32,depth_or_array_layers:1};let texture=device.create_texture(&wgpu::TextureDescriptor{label:Some("offscreen world normal"),size,mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Rgba32Float,usage:wgpu::TextureUsages::RENDER_ATTACHMENT|wgpu::TextureUsages::COPY_SRC,view_formats:&[]});let view=texture.create_view(&Default::default());let depth=device.create_texture(&wgpu::TextureDescriptor{label:Some("depth"),size,mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Depth32Float,usage:wgpu::TextureUsages::RENDER_ATTACHMENT,view_formats:&[]});let depth_view=depth.create_view(&Default::default());let shader=device.create_shader_module(wgpu::ShaderModuleDescriptor{label:Some("normal pass"),source:wgpu::ShaderSource::Wgsl("struct V { @builtin(position) p:vec4<f32>, @location(0) n:vec3<f32> }; @vertex fn vs(@location(0) p:vec4<f32>,@location(1) n:vec3<f32>)->V{var o:V;o.p=p;o.n=n;return o;} @fragment fn fs(v:V)->@location(0) vec4<f32>{return vec4<f32>(normalize(v.n)*0.5+vec3<f32>(0.5),1.0);}".into())});let attributes=[wgpu::VertexAttribute{format:wgpu::VertexFormat::Float32x4,offset:0,shader_location:0},wgpu::VertexAttribute{format:wgpu::VertexFormat::Float32x3,offset:16,shader_location:1}];let layout=wgpu::VertexBufferLayout{array_stride:28,step_mode:wgpu::VertexStepMode::Vertex,attributes:&attributes};let pipeline=device.create_render_pipeline(&wgpu::RenderPipelineDescriptor{label:Some("raw normal"),layout:None,vertex:wgpu::VertexState{module:&shader,entry_point:Some("vs"),compilation_options:Default::default(),buffers:&[Some(layout)]},primitive:wgpu::PrimitiveState{cull_mode:None,..Default::default()},depth_stencil:Some(wgpu::DepthStencilState{format:wgpu::TextureFormat::Depth32Float,depth_write_enabled:Some(true),depth_compare:Some(wgpu::CompareFunction::Less),stencil:Default::default(),bias:Default::default()}),multisample:Default::default(),fragment:Some(wgpu::FragmentState{module:&shader,entry_point:Some("fs"),compilation_options:Default::default(),targets:&[Some(wgpu::ColorTargetState{format:wgpu::TextureFormat::Rgba32Float,blend:None,write_mask:wgpu::ColorWrites::ALL})]}),multiview_mask:None,cache:None});let(row,total)=super::backend::readback_layout(w,h)?;let readback=device.create_buffer(&wgpu::BufferDescriptor{label:Some("readback"),size:total as u64,usage:wgpu::BufferUsages::COPY_DST|wgpu::BufferUsages::MAP_READ,mapped_at_creation:false});let mut encoder=device.create_command_encoder(&Default::default());{let mut pass=encoder.begin_render_pass(&wgpu::RenderPassDescriptor{label:Some("offscreen"),color_attachments:&[Some(wgpu::RenderPassColorAttachment{view:&view,depth_slice:None,resolve_target:None,ops:wgpu::Operations{load:wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),store:wgpu::StoreOp::Store}})],depth_stencil_attachment:Some(wgpu::RenderPassDepthStencilAttachment{view:&depth_view,depth_ops:Some(wgpu::Operations{load:wgpu::LoadOp::Clear(1.),store:wgpu::StoreOp::Store}),stencil_ops:None}),timestamp_writes:None,occlusion_query_set:None,multiview_mask:None});pass.set_pipeline(&pipeline);pass.set_vertex_buffer(0,buffer.slice(..));pass.draw(0..count,0..1);}encoder.copy_texture_to_buffer(wgpu::TexelCopyTextureInfo{texture:&texture,mip_level:0,origin:wgpu::Origin3d::ZERO,aspect:wgpu::TextureAspect::All},wgpu::TexelCopyBufferInfo{buffer:&readback,layout:wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(row as u32),rows_per_image:Some(h as u32)}},size);queue.submit([encoder.finish()]);let(tx,rx)=std::sync::mpsc::channel();readback.map_async(wgpu::MapMode::Read,..,move|r|{let _=tx.send(r);});device.poll(wgpu::PollType::Wait{submission_index:None,timeout:Some(std::time::Duration::from_secs(20))}).map_err(|e|e.to_string())?;rx.recv_timeout(std::time::Duration::from_secs(2)).map_err(|e|e.to_string())?.map_err(|e|e.to_string())?;let mapped=readback.get_mapped_range(..).map_err(|e|e.to_string())?;let mut f=Frame::try_new(w,h)?;for y in 0..h{for x in 0..w*4{let i=y*row+x*4;let value=f32::from_le_bytes(mapped[i..i+4].try_into().map_err(|_|"readback bytes")?);if !value.is_finite(){return Err("nonfinite GPU framebuffer".into());}f.d[y*w*4+x]=value;}}drop(mapped);readback.unmap();Ok((f,name))}
#[cfg(test)]mod tests{use super::*;#[test]fn cpu_normal_fallback_explicit(){let g=super::super::primitives::generate(&super::super::primitives::Primitive::Sphere{radius:1.,longitude_slices:16,latitude_slices:8}).unwrap();let s=Stream{vertices:g.vertices,indices:g.indices};let c=Camera{eye:[0.,0.,-4.],pan:0.,tilt:0.,roll:0.,sensor_height:24.,focal_length:35.,near:0.1};let f=normal_reference(&s,&c,64,64).unwrap();assert!(f.d.iter().all(|v|v.is_finite()));assert!(f.d.chunks_exact(4).any(|p|p[3]==1.));}}
